class Solution:
    def numberOfAlternatingGroups(self, colors: List[int], queries: List[List[int]]) -> List[int]:
        n = len(colors)
        result = []

        def is_alternating(start, size):
            # Check if segment from start to start+size-1 is alternating
            # In circular arrangement, we need to check wrap-around
            for i in range(size - 1):
                # Current position and next position
                pos1 = (start + i) % n
                pos2 = (start + i + 1) % n
                if colors[pos1] == colors[pos2]:
                    return False

            # Check the wrap-around from last to first (if size > 1)
            if size > 1:
                # Last position of segment to first position
                pos1 = (start + size - 1) % n
                pos2 = start % n
                if colors[pos1] == colors[pos2]:
                    return False

            return True

        for query in queries:
            if query[0] == 1:  # Count alternating groups of size size
                size = query[1]
                count = 0
                for start in range(n):
                    if is_alternating(start, size):
                        count += 1
                result.append(count)
            else:  # Type 2: update color
                index, color = query[1], query[2]
                colors[index] = color

        return result

