class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        # Start at position 0 (top-left corner: row 0, column 0)
        row, col = 0, 0

        # Process each command
        for command in commands:
            if command == "RIGHT":
                col += 1
            elif command == "LEFT":
                col -= 1
            elif command == "DOWN":
                row += 1
            elif command == "UP":
                row -= 1

        # Calculate final position: row * n + col
        return row * n + col

class Solution:
    def winningPlayerCount(self, n: int, pick: List[List[int]]) -> int:
        # Dictionary to store count of balls of each color for each player
        player_color_count = {}

        # Initialize for all players
        for i in range(n):
            player_color_count[i] = {}

        # Process each pick
        for player, color in pick:
            if color not in player_color_count[player]:
                player_color_count[player][color] = 0
            player_color_count[player][color] += 1

        # Count how many players win
        winners = 0

        # Check each player from 0 to n-1
        for i in range(n):
            # Find the maximum count of any single color picked by player i
            max_count = 0
            if player_color_count[i]:  # If player has picked at least one ball
                for color in player_color_count[i]:
                    max_count = max(max_count, player_color_count[i][color])

            # Player i wins if they have at least (i+1) balls of the same color
            if max_count >= i + 1:
                winners += 1

        return winners

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        # Calculate minimum flips needed for all rows to be palindromic
        rows_flips = 0
        for i in range(m):
            for j in range(n // 2):
                # Compare symmetric positions in row i
                if grid[i][j] != grid[i][n - 1 - j]:
                    rows_flips += 1

        # Calculate minimum flips needed for all columns to be palindromic
        cols_flips = 0
        for j in range(n):
            for i in range(m // 2):
                # Compare symmetric positions in column j
                if grid[i][j] != grid[m - 1 - i][j]:
                    cols_flips += 1

        # Return the minimum of the two options
        return min(rows_flips, cols_flips)

